export default function ProjectsSection({ isHomePage = false }: { isHomePage?: boolean } = {}) {
  const sectionRef = useRef<HTMLDivElement>(null);
  const [filters, setFilters] = useState<FilterState | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [isInitialized, setIsInitialized] = useState(false);
  const itemsPerPage = 18;

  const previousFilters = useRef<FilterState | null>(null);

  // Load page number from sessionStorage on initial client-side mount
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const savedPage = sessionStorage.getItem('projects_current_page');
      if (savedPage) {
        const parsed = parseInt(savedPage, 10);
        if (!isNaN(parsed) && parsed > 0) {
          setCurrentPage(parsed);
        }
      }
    }
    setIsInitialized(true);
  }, []);

  // Save page number to sessionStorage whenever it changes, but only after initialization
  useEffect(() => {
    if (isInitialized && typeof window !== 'undefined') {
      sessionStorage.setItem('projects_current_page', currentPage.toString());
    }
  }, [currentPage, isInitialized]);

  // Deep comparison helper for FilterState
  const areFiltersEqual = (a: FilterState | null, b: FilterState | null): boolean => {
    if (a === b) return true;
    if (!a || !b) return false;
    return (
      a.emirate === b.emirate &&
      a.category === b.category &&
      a.propertyType === b.propertyType &&
      a.fromPrice === b.fromPrice &&
      a.toPrice === b.toPrice &&
      a.searchQuery === b.searchQuery
    );
  };

  // Reset page when filters change (ignoring the initial mount-triggered filter calls)
  useEffect(() => {
    if (previousFilters.current !== null && !areFiltersEqual(previousFilters.current, filters)) {
      setCurrentPage(1);
      if (typeof window !== 'undefined') {
        sessionStorage.setItem('projects_current_page', '1');
      }
    }
    previousFilters.current = filters;
  }, [filters]);



  useEffect(() => {
    // Immediately ensure all cards are visible
    if (typeof window !== 'undefined') {
      const cards = document.querySelectorAll('.project-card');
      cards.forEach((card) => {
        (card as HTMLElement).style.opacity = '1';
        (card as HTMLElement).style.transform = 'translateY(0)';
      });
    }

    if (typeof window === 'undefined' || !('IntersectionObserver' in window)) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const cards = entry.target.querySelectorAll('.project-card');
            cards.forEach((card) => {
              (card as HTMLElement).style.opacity = '1';
              (card as HTMLElement).style.transform = 'translateY(0)';
            });
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0, rootMargin: '200px 0px' }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, [filters, currentPage]); // Re-run animation when filters or page changes

  const filteredProjects = projects.filter(project => {
    if (!filters) return true;

    // Emirate filter (Dubai, Abu Dhabi, etc.)
    if (filters.emirate && filters.emirate !== 'all') {
      const formattedEmirate = filters.emirate.replace('-', ' ').toLowerCase();
      if (!project.location.toLowerCase().includes(formattedEmirate)) return false;
    }

    // Category (Status) filter (Off-Plan, Resale, Rentals)
    if (filters.category && filters.category !== 'all') {
      if (project.status?.toLowerCase() !== filters.category.toLowerCase()) return false;
    }

    // Property Type filter
    if (filters.propertyType && filters.propertyType !== 'all') {
      const type = filters.propertyType.toLowerCase();
      const textToSearch = `${project.category} ${project.title} ${project.description}`.toLowerCase();
      // Drop the 's' for basic simple matching (e.g., 'apartments' -> 'apartment')
      const singularTerm = type.endsWith('s') ? type.slice(0, -1) : type;
      if (!textToSearch.includes(singularTerm) && !textToSearch.includes(type)) {
        return false;
      }
    }

    // Simple text search
    if (filters.searchQuery) {
      const q = filters.searchQuery.toLowerCase();
      const textToSearch = `${project.title} ${project.location}`.toLowerCase();
      if (!textToSearch.includes(q)) return false;
    }

    // Price filtering
    if (filters.fromPrice) {
      const minPrice = parseInt(filters.fromPrice.replace(/\D/g, ''), 10);
      if (!isNaN(minPrice) && project.basePriceAED > 0) {
        // Assume minPrice is in USD, let's roughly convert basePriceAED to USD for comparison (divide by ~3.67)
        // Actually, let's just assume the user inputs AED for simplicity if they aren't explicit, or we compare directly.
        // The UI says "USD" but data is basePriceAED. We'll convert AED to USD for the check: USD = AED / 3.67
        const projectUSDPrice = project.basePriceAED / 3.67;
        if (projectUSDPrice < minPrice) return false;
      }
    }

    if (filters.toPrice) {
      const maxPrice = parseInt(filters.toPrice.replace(/\D/g, ''), 10);
      if (!isNaN(maxPrice) && project.basePriceAED > 0) {
        const projectUSDPrice = project.basePriceAED / 3.67;
        if (projectUSDPrice > maxPrice) return false;
      }
    }

    return true;
  });

  const availableLocations = Array.from(new Set(
    projects.map(p => p.location.split(',')[0].trim()) // just the first part maybe, or full location? The user said "emirates box should be named as location by default on selection it should be location name also locations should be updated from locations on cards data similarly names, area, community". Let's just use the full location name from card data.
  ));

  const availableSuggestions = Array.from(new Set(
    projects.flatMap(p => [p.title, p.location])
  ));

  const totalPages = Math.ceil(filteredProjects.length / itemsPerPage);
  const currentProjects = isHomePage
    ? filteredProjects.slice(0, 6)
    : filteredProjects.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  // Keep currentPage within totalPages bounds if totalPages changes
  useEffect(() => {
    if (isInitialized && totalPages > 0 && currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [totalPages, currentPage, isInitialized]);

  return (
    <section
      ref={sectionRef}
      style={{
        backgroundColor: '#ffffff', // Set main bg to White
        padding: 'clamp(45px, 7.5vw, 117px) clamp(20px, 6vw, 100px)'
      }}>
      <style>{`
        .view-all-projects-btn:hover {
          background-color: #e0c996 !important;
          border-color: #e0c996 !important;
          color: #02042d !important;
        }
      `}</style>

      {/* Header */}
      <div style={{ maxWidth: '1400px', margin: '0 auto' }}>

        {/* Featured Projects heading - styled like WorkCollection */}
        <AnimatedHeading
          text="Featured Projects"
          style={{
            fontFamily: 'Uxum Grotesque Regular, sans-serif',
            fontSize: 'clamp(40px, 8vw, 112px)',
            letterSpacing: 'clamp(-2px, -0.6vw, -6.8px)',
            lineHeight: '1em',
            color: '#02042d', // Dark Gray
            margin: '0 0 clamp(16px, 2vw, 32px) 0',
            fontWeight: 400
          }}
        />

        <h2
          style={{
            fontFamily: 'Uxum Grotesque Regular, sans-serif',
            fontSize: 'clamp(28px, 4vw, 52px)',
            fontWeight: 400,
            color: '#555555', // Lite Gray
            lineHeight: 1.15,
            maxWidth: '1200px',
            marginBottom: 'clamp(24px, 3vw, 40px)'
          }}>
          Discover handpicked UAE off‑plan opportunities with key investment highlights and project visuals.
        </h2>

        {/* Search Filters */}
        <ProjectSearchFilters
          onFilterChange={setFilters}
          availableSuggestions={availableSuggestions}
          availableLocations={availableLocations}
        />

        {/* Divider */}
        <div
          style={{
            width: '100%',
            height: '1px',
            backgroundColor: '#02042d', // Keep divider dark gray for contrast
            opacity: 0.15,
            marginBottom: 'clamp(32px, 4vw, 56px)'
          }} />

        {/* Cards Grid */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 400px), 1fr))',
            gap: 'clamp(12px, 2vw, 24px)'
          }}>
          {currentProjects.length > 0 ? (
            currentProjects.map((project, index) => (
              <ProjectCard key={project.id} project={project} index={(currentPage - 1) * itemsPerPage + index} />
            ))
          ) : (
            <div style={{
              gridColumn: '1 / -1',
              padding: '60px 0',
              textAlign: 'center',
              fontFamily: 'Uxum Grotesque Regular, sans-serif',
              fontSize: '20px',
              color: '#555'
            }}>
              No projects found matching your criteria.
            </div>
          )}
        </div>

        {/* Pagination */
          !isHomePage && totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: '40px', gap: '8px' }}>
              <button
                onClick={() => {
                  setCurrentPage(p => Math.max(1, p - 1));
                  sectionRef.current?.scrollIntoView({ behavior: 'smooth' });
                }}
                disabled={currentPage === 1}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: '40px',
                  height: '40px',
                  border: '1px solid #e0c996',
                  backgroundColor: '#ffffff',
                  color: '#e0c996',
                  cursor: currentPage === 1 ? 'not-allowed' : 'pointer',
                  opacity: currentPage === 1 ? 0.5 : 1,
                  transition: 'all 0.3s ease',
                }}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
              </button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                <button
                  key={page}
                  onClick={() => {
                    setCurrentPage(page);
                    sectionRef.current?.scrollIntoView({ behavior: 'smooth' });
                  }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '40px',
                    height: '40px',
                    border: '1px solid #e0c996',
                    backgroundColor: currentPage === page ? '#e0c996' : '#ffffff',
                    color: currentPage === page ? '#ffffff' : '#e0c996',
                    fontFamily: 'Uxum Grotesque Regular, sans-serif',
                    fontSize: '16px',
                    cursor: 'pointer',
                    transition: 'all 0.3s ease',
                  }}
                >
                  {page}
                </button>
              ))}
              <button
                onClick={() => {
                  setCurrentPage(p => Math.min(totalPages, p + 1));
                  sectionRef.current?.scrollIntoView({ behavior: 'smooth' });
                }}
                disabled={currentPage === totalPages}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: '40px',
                  height: '40px',
                  border: '1px solid #e0c996',
                  backgroundColor: '#ffffff',
                  color: '#e0c996',
                  cursor: currentPage === totalPages ? 'not-allowed' : 'pointer',
                  opacity: currentPage === totalPages ? 0.5 : 1,
                  transition: 'all 0.3s ease',
                }}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
              </button>
            </div>
          )}

        {/* View All Projects Button (for Home Page) */}
        {isHomePage && (
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: '48px' }}>
            <Link
              href="/projects"
              className="view-all-projects-btn"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '12px',
                padding: '16px 40px',
                border: '1px solid #02042d',
                backgroundColor: '#02042d',
                color: '#ffffff',
                fontFamily: 'Uxum Grotesque Regular, sans-serif',
                fontSize: '14px',
                letterSpacing: '0.08em',
                textTransform: 'uppercase',
                textDecoration: 'none',
                transition: 'all 0.3s ease',
              }}
            >
              <span>View All Projects</span>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="5" y1="12" x2="19" y2="12"></line>
                <polyline points="12 5 19 12 12 19"></polyline>
              </svg>
            </Link>
          </div>
        )}
      </div>
    </section>
  );
}
