'use client';
import React, { useState, useRef, useEffect } from 'react';

// Common Dropdown definitions
interface DropdownOption {
  label: string;
  value?: string;
  isHeader?: boolean;
  indent?: boolean;
}

const PROPERTY_TYPES: DropdownOption[] = [
  { label: 'All', value: 'all' },
  { label: 'Residential', isHeader: true },
  { label: 'Apartments', value: 'apartments', indent: true },
  { label: 'Duplexes', value: 'duplexes', indent: true },
  { label: 'Penthouses', value: 'penthouses', indent: true },
  { label: 'Residential Buildings', value: 'residential_buildings', indent: true },
  { label: 'Townhouses', value: 'townhouses', indent: true },
  { label: 'Villas', value: 'villas', indent: true },
  { label: 'Commercial', isHeader: true },
  { label: 'Offices', value: 'offices', indent: true },
  { label: 'Retail', value: 'retail', indent: true },
];

const CATEGORIES: DropdownOption[] = [
  { label: 'All', value: 'all' },
  { label: 'Off-Plan', value: 'off-plan' },
  { label: 'Resale', value: 'resale' },
  { label: 'Rentals', value: 'rentals' },
];

// Emirate/Location options will be generated dynamically

const LightDropdown = ({ 
  value, 
  onChange, 
  options, 
  placeholder 
}: { 
  value: string, 
  onChange: (val: string) => void, 
  options: DropdownOption[], 
  placeholder: string 
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
        setFocused(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const selectedOption = options.find(o => o.value === value);

  return (
    <div ref={containerRef} className="relative w-full h-full">
      <div 
        onClick={() => { setIsOpen(!isOpen); setFocused(!isOpen); }}
        className="w-full h-full flex items-center"
        style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: '15px',
          border: '1px solid #d1d1d1',
          padding: '14px 36px 14px 16px',
          outline: 'none',
          transition: 'border-color 0.2s, box-shadow 0.2s',
          backgroundColor: '#fafafa',
          color: value ? '#02042d' : '#555',
          cursor: 'pointer',
          userSelect: 'none',
          borderColor: focused ? '#02042d' : '#d1d1d1',
          minHeight: '48px'
        }}
      >
        {selectedOption ? selectedOption.label : placeholder}
        <svg fill="none" className={`absolute right-4 pointer-events-none transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} width="14" height="14" viewBox="0 0 24 24">
          <path d="M6 9l6 6 6-6" stroke="#999" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </div>

      {isOpen && (
        <div style={{
          position: 'absolute',
          top: 'calc(100% + 4px)',
          left: 0,
          right: 0,
          backgroundColor: '#ffffff',
          maxHeight: '280px',
          overflowY: 'auto',
          zIndex: 50,
          boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
          border: '1px solid #e5e5e5',
          padding: '8px 0',
        }}>
          {options.map((opt, i) => {
            if (opt.isHeader) {
              return (
                <div key={i} style={{ padding: '8px 16px', color: '#999', fontSize: '13px', fontFamily: 'Uxum Grotesque Regular, sans-serif', paddingTop: i === 0 ? '8px' : '16px' }}>
                  {opt.label}
                </div>
              );
            }
            return (
              <div 
                key={i}
                onClick={() => { onChange(opt.value!); setIsOpen(false); setFocused(false); }}
                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f5f5f5'}
                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                style={{ 
                  padding: `8px 16px 8px ${opt.indent ? '32px' : '16px'}`, 
                  color: '#02042d', 
                  fontSize: '15px',
                  fontFamily: 'Uxum Grotesque Regular, sans-serif',
                  cursor: 'pointer',
                  transition: 'background-color 0.15s'
                }}
              >
                {opt.label}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

const PriceDropdown = ({
  fromPrice,
  toPrice,
  setFromPrice,
  setToPrice
}: {
  fromPrice: string;
  toPrice: string;
  setFromPrice: (val: string) => void;
  setToPrice: (val: string) => void;
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
        setFocused(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const displayLabel = fromPrice || toPrice 
    ? `${fromPrice ? 'from USD ' + fromPrice : ''} ${fromPrice && toPrice ? '-' : ''} ${toPrice ? 'to USD ' + toPrice : ''}`
    : 'Price';

  return (
    <div ref={containerRef} className="relative w-full h-full">
      <div 
        onClick={() => { setIsOpen(!isOpen); setFocused(!isOpen); }}
        className="w-full h-full flex items-center"
        style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: '15px',
          border: '1px solid #d1d1d1',
          padding: '14px 36px 14px 16px',
          outline: 'none',
          transition: 'border-color 0.2s, box-shadow 0.2s',
          backgroundColor: '#fafafa',
          color: (fromPrice || toPrice) ? '#02042d' : '#555',
          cursor: 'pointer',
          userSelect: 'none',
          borderColor: focused ? '#02042d' : '#d1d1d1',
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          minHeight: '48px'
        }}
      >
        {displayLabel}
        <svg fill="none" className={`absolute right-4 pointer-events-none transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} width="14" height="14" viewBox="0 0 24 24">
          <path d="M6 9l6 6 6-6" stroke="#999" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </div>

      {isOpen && (
        <div style={{
          position: 'absolute',
          top: 'calc(100% + 4px)',
          left: 0,
          width: '280px',
          backgroundColor: '#ffffff',
          zIndex: 50,
          boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
          border: '1px solid #e5e5e5',
          padding: '16px',
          display: 'flex',
          flexDirection: 'column',
          gap: '12px'
        }}>
          <div style={{ display: 'flex', gap: '8px' }}>
            <input 
              type="text" 
              placeholder="from"
              value={fromPrice}
              onChange={(e) => setFromPrice(e.target.value)}
              style={{
                width: '50%',
                padding: '10px 12px',
                border: '1px solid #d1d1d1',
                fontSize: '14px',
                outline: 'none',
                fontFamily: 'Uxum Grotesque Regular, sans-serif',
                transition: 'border-color 0.2s'
              }}
              onFocus={(e) => e.target.style.borderColor = '#02042d'}
              onBlur={(e) => e.target.style.borderColor = '#d1d1d1'}
            />
            <input 
              type="text" 
              placeholder="to"
              value={toPrice}
              onChange={(e) => setToPrice(e.target.value)}
              style={{
                width: '50%',
                padding: '10px 12px',
                border: '1px solid #d1d1d1',
                fontSize: '14px',
                outline: 'none',
                fontFamily: 'Uxum Grotesque Regular, sans-serif',
                transition: 'border-color 0.2s'
              }}
              onFocus={(e) => e.target.style.borderColor = '#02042d'}
              onBlur={(e) => e.target.style.borderColor = '#d1d1d1'}
            />
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-start' }}>
            <button 
              onClick={() => { setIsOpen(false); setFocused(false); }}
              style={{
                backgroundColor: '#02042d',
                color: '#fff',
                border: 'none',
                padding: '10px 32px',
                fontFamily: 'Uxum Grotesque Regular, sans-serif',
                fontSize: '14px',
                cursor: 'pointer',
                transition: 'background-color 0.2s'
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#02042d'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#02042d'}
            >
              Apply
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export interface FilterState {
  emirate: string;
  category: string;
  propertyType: string;
  fromPrice: string;
  toPrice: string;
  searchQuery: string;
}

export default function ProjectSearchFilters({ 
  onFilterChange,
  availableSuggestions = [],
  availableLocations = []
}: { 
  onFilterChange: (filters: FilterState) => void,
  availableSuggestions?: string[],
  availableLocations?: string[]
}) {
  const [emirate, setEmirate] = useState('');
  const [category, setCategory] = useState('');
  const [propertyType, setPropertyType] = useState('');
  const [fromPrice, setFromPrice] = useState('');
  const [toPrice, setToPrice] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const handleSearchClick = () => {
    onFilterChange({
      emirate,
      category,
      propertyType,
      fromPrice,
      toPrice,
      searchQuery
    });
  };

  // Trigger search on any dropdown change automatically or wait for search button?
  // Let's rely on the search button for now, as there's a explicit Search button.
  useEffect(() => {
    // Optionally auto-filter on dropdowns, but user image has a Search button.
    // We will auto-filter on category and property type as a nice touch, or just rely on search button.
    handleSearchClick();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [emirate, category, propertyType, fromPrice, toPrice]);

  const filteredSuggestions = availableSuggestions.filter(s => 
    s.toLowerCase().includes(searchQuery.toLowerCase())
  ).slice(0, 5);

  const LOCATION_OPTIONS: DropdownOption[] = [
    { label: 'All', value: 'all' },
    ...availableLocations.map(loc => ({ label: loc, value: loc }))
  ];

  return (
    <div style={{ width: '100%', marginBottom: 'clamp(32px, 4vw, 56px)' }}>
      {/* Row 1 */}
      <div className="flex flex-col md:flex-row" style={{ gap: '16px', marginBottom: '16px' }}>
        <div style={{ width: '100%', height: '48px' }} className="md:max-w-[188px] md:w-[188px] md:flex-none">
          <LightDropdown value={emirate} onChange={setEmirate} options={LOCATION_OPTIONS} placeholder="Location" />
        </div>
        <div style={{ flex: '1 1 auto', position: 'relative', height: '48px' }}>
          <div style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {/* House Search Icon */}
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#bfaa7c" strokeWidth="1.5">
              <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" strokeLinecap="round" strokeLinejoin="round"/>
              <circle cx="15" cy="15" r="3" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M17 17l2 2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <input 
            type="text" 
            placeholder="Area, Community, Building" 
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setShowSuggestions(true);
            }}
            onFocus={() => {
              setIsSearchFocused(true);
              setShowSuggestions(true);
            }}
            onBlur={() => {
              setIsSearchFocused(false);
              setTimeout(() => setShowSuggestions(false), 200);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                handleSearchClick();
                setShowSuggestions(false);
              }
            }}
            style={{
              width: '100%',
              height: '100%',
              minHeight: '48px',
              padding: '14px 16px 14px 44px',
              fontFamily: 'Uxum Grotesque Regular, sans-serif',
              fontSize: '15px',
              border: '1px solid #d1d1d1',
              borderColor: isSearchFocused ? '#02042d' : '#d1d1d1',
              outline: 'none',
              backgroundColor: '#fafafa',
              color: '#02042d',
              transition: 'border-color 0.2s'
            }}
          />
          {/* Autocomplete Suggestions */}
          {showSuggestions && searchQuery.length > 0 && filteredSuggestions.length > 0 && (
            <div style={{
              position: 'absolute',
              top: 'calc(100% + 4px)',
              left: 0,
              right: 0,
              backgroundColor: '#ffffff',
              zIndex: 60,
              boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
              border: '1px solid #e5e5e5',
              padding: '8px 0',
            }}>
              {filteredSuggestions.map((suggestion, idx) => (
                <div 
                  key={idx}
                  onMouseDown={(e) => {
                    e.preventDefault(); // Prevents blur on the input from firing immediately
                    setSearchQuery(suggestion);
                    setShowSuggestions(false);
                  }}
                  onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f5f5f5'}
                  onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                  style={{
                    padding: '8px 16px',
                    color: '#02042d',
                    fontSize: '15px',
                    fontFamily: 'Uxum Grotesque Regular, sans-serif',
                    cursor: 'pointer',
                  }}
                >
                  {suggestion}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
      
      {/* Row 2 */}
      <div className="flex flex-col md:flex-row" style={{ gap: '16px' }}>
        <div style={{ width: '100%', height: '48px' }} className="md:max-w-[188px] md:w-[188px] md:flex-none">
          <LightDropdown value={category} onChange={setCategory} options={CATEGORIES} placeholder="Property category" />
        </div>
        <div style={{ width: '100%', height: '48px' }} className="md:max-w-[188px] md:w-[188px] md:flex-none">
          <LightDropdown value={propertyType} onChange={setPropertyType} options={PROPERTY_TYPES} placeholder="Property type" />
        </div>
        <div style={{ width: '100%', height: '48px' }} className="md:max-w-[188px] md:w-[188px] md:flex-none">
          <PriceDropdown 
            fromPrice={fromPrice} 
            toPrice={toPrice} 
            setFromPrice={setFromPrice} 
            setToPrice={setToPrice} 
          />
        </div>
        <div style={{ flex: '1 1 auto', display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }}>
          <button 
            onClick={handleSearchClick}
            style={{
              backgroundColor: '#02042d',
              color: '#ffffff',
              border: 'none',
              padding: '0 48px',
              fontFamily: 'Uxum Grotesque Regular, sans-serif',
              fontSize: '15px',
              cursor: 'pointer',
              height: '48px',
              transition: 'background-color 0.2s',
              lineHeight: '48px'
            }}
            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#02042d'}
            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#02042d'}
          >
            Search
          </button>
        </div>
      </div>
    </div>
  );
}
